const evt = $input.first().json.body || {};
const data = evt.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const fromMe = key.fromMe === true;
const msg = data.message || {};
const text = ((msg.conversation != null ? msg.conversation : (msg.extendedTextMessage && msg.extendedTextMessage.text)) || '').trim();
if (fromMe || remoteJid.endsWith('@g.us') || !text) { return []; }
const number = remoteJid.split('@')[0];
const tz = 'America/Argentina/Buenos_Aires';
const fmt = new Intl.DateTimeFormat('es-AR', { timeZone: tz, weekday:'long', year:'numeric', month:'2-digit', day:'2-digit' });
const p = Object.fromEntries(fmt.formatToParts(new Date()).map(x=>[x.type,x.value]));
const hoy = p.year + '-' + p.month + '-' + p.day;
const sys = 'Sos el asistente de reservas de un complejo de canchas de futbol en Argentina (timezone America/Argentina/Buenos_Aires). Hoy es ' + hoy + ' (' + p.weekday + '). Canchas: "Cancha 1", "Cancha 2". Horario: 16:00 a 23:00, turnos de 1 hora. Extrae intencion y datos del mensaje. Resolve fechas relativas a YYYY-MM-DD. Horas a HH:MM 24h. Si falta un dato, null.';
const geminiBody = { systemInstruction: { parts: [{ text: sys }] }, contents: [{ role:'user', parts:[{ text: text }] }], generationConfig: { temperature:0, responseMimeType:'application/json', responseSchema: { type:'object', properties: { intent:{type:'string',enum:['consultar_disponibilidad','reservar','cancelar','saludo','otro']}, cancha:{type:'string',nullable:true}, fecha:{type:'string',nullable:true}, hora:{type:'string',nullable:true} }, required:['intent'] } } };
return [{ json: { number, text, hoy, geminiBody } }];

const prep = $('Preparar').first().json;
let parsed = {};
try { parsed = JSON.parse($input.first().json.candidates[0].content.parts[0].text); } catch(e){ parsed = { intent:'otro', _err:String(e) }; }
return [{ json: { number: prep.number, text: prep.text, hoy: prep.hoy, parsed } }];

const pp = $('Parsear').first().json;
const number = pp.number;
const parsed = pp.parsed || { intent:'otro' };
const canchas = $input.all().map(i => i.json);
const intent = parsed.intent;
function find(nombre){ if(!nombre) return null; const n=String(nombre).toLowerCase(); return canchas.find(c=>c.nombre.toLowerCase()===n) || canchas.find(c=>c.nombre.toLowerCase().includes(n)||n.includes(c.nombre.toLowerCase())); }
if (intent==='saludo') return [{ json:{ number, ready:false, replyText:'Hola! Soy el bot de reservas de __NOMBRE_COMPLEJO__. Decime que cancha y para cuando queres jugar (ej: "Cancha 1 el viernes a las 20").' } }];
if (intent!=='consultar_disponibilidad' && intent!=='reservar') return [{ json:{ number, ready:false, replyText:'Puedo ayudarte a ver disponibilidad y reservar. Decime cancha, dia y hora.' } }];
const cancha = find(parsed.cancha);
if (!cancha) return [{ json:{ number, ready:false, replyText:'Que cancha queres? Tenemos: '+canchas.map(c=>c.nombre).join(', ')+'.' } }];
if (!parsed.fecha) return [{ json:{ number, ready:false, replyText:'Para que dia? (ej: viernes o manana)' } }];
return [{ json:{ number, ready:true, canchaId:cancha.id, canchaNombre:cancha.nombre, fecha:parsed.fecha, horaPedida:parsed.hora||null } }];

const res = $input.first().json;
const dec = $('Decidir').first().json;
const number = dec.number;
const slots = res.slots || [];
let replyText;
if (!slots.length) replyText = 'No hay turnos libres en '+dec.canchaNombre+' para el '+res.fecha+'. Proba otro dia.';
else replyText = 'Turnos libres en '+dec.canchaNombre+' el '+res.fecha+':\n'+slots.map(s=>s.horaInicio).join(', ')+'\n\nDecime cual queres y te lo reservo.';
return [{ json:{ number, replyText } }];
